        if not spans:
            doc_name = str(doc.get("doc_name") or "")
            m = re.search(r"(?:dated[-_]?)(\d{4}-\d{2}-\d{2})", doc_name, flags=re.IGNORECASE)
            if m:
                add_span(spans, seen, m.group(1))

